Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher),
      (a)-[:FROM_CHUNK]->(c:Chunk)-[:FROM_DOCUMENT]->(d:Document)
WHERE (
  toLower(p.name) CONTAINS 'techcrunch' OR
  any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch')
)
AND (
  (
    (toLower(a.published_on) CONTAINS '2023-10' OR toLower(a.published_on) CONTAINS 'october 2023')
    AND (
      toLower(d.title) CONTAINS 'hardware' OR toLower(d.title) CONTAINS 'pixel' OR
      toLower(d.title) CONTAINS 'made by google' OR toLower(a.name) CONTAINS 'hardware' OR
      toLower(a.name) CONTAINS 'pixel' OR toLower(a.name) CONTAINS 'made by google'
    )
  )
  OR
  (
    (toLower(a.published_on) CONTAINS '2023-11-13' OR toLower(a.published_on) CONTAINS 'november 13, 2023')
    AND (
      toLower(d.title) CONTAINS 'search' OR toLower(d.title) CONTAINS 'default' OR
      toLower(d.title) CONTAINS 'spending' OR toLower(a.name) CONTAINS 'search' OR
      toLower(a.name) CONTAINS 'default' OR toLower(a.name) CONTAINS 'spending'
    )
  )
  OR
  (
    (toLower(a.published_on) CONTAINS '2023-12-15' OR toLower(a.published_on) CONTAINS 'december 15, 2023')
    AND (
      toLower(d.title) CONTAINS 'antitrust' OR toLower(d.title) CONTAINS 'class action' OR
      toLower(d.title) CONTAINS 'lawsuit' OR toLower(a.name) CONTAINS 'antitrust' OR
      toLower(a.name) CONTAINS 'class action' OR toLower(a.name) CONTAINS 'lawsuit'
    )
  )
)
OPTIONAL MATCH (a)-[:MENTIONS]->(e:__Entity__)
RETURN a.name AS article, a.published_on AS published_on, d.title AS page,
       collect(DISTINCT e.name) AS connected_entities, c.text AS passage
LIMIT 10
