Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher)
WHERE (
  toLower(a.published_on) CONTAINS '2023-10-01'
  OR toLower(a.published_on) CONTAINS 'october 1, 2023'
  OR toLower(a.published_on) CONTAINS '2023-11-05'
  OR toLower(a.published_on) CONTAINS 'november 5, 2023'
)
AND (
  toLower(p.name) CONTAINS 'sydney morning herald'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sydney morning herald')
)
MATCH (a)-[:FROM_CHUNK]->(c:Chunk)
OPTIONAL MATCH (a)-[r:MENTIONS|PART_OF]->(e:__Entity__)
WHERE (
  toLower(e.name) CONTAINS 'federal reserve'
  OR toLower(e.name) CONTAINS 'fed'
  OR toLower(e.name) CONTAINS 'rate'
  OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'federal reserve' OR toLower(alias) CONTAINS 'fed' OR toLower(alias) CONTAINS 'rate')
)
RETURN a.name AS article, a.published_on AS published_on, p.name AS publisher, c.text AS passage,
       collect(DISTINCT {entity: e.name, relationship: type(r)}) AS connections
LIMIT 10
